<?php require __DIR__.'/../bootstrap.php';messenger_run(function($u){MessengerSecurity::requirePermission('messenger.admin.settings','edit');$in=messenger_input();foreach($in as $key=>$value){if(!is_string($key)||!str_starts_with($key,'messenger.')||in_array($key,['messenger.realtime_secret','messenger.realtime_internal_key'],true))continue;Database::execute('INSERT INTO chat_settings(setting_key,setting_value,updated_by,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=NOW()',[$key,MessengerSecurity::text($value,1000),(int)$u['id']]);}MessengerService::audit((int)$u['id'],'settings_updated');return ['updated'=>true];},true);
